	@Test
	void demandsPartitionTheirPrunableAxisAndPublishBoundedPayloadPages(@TempDir File dataDir) {
		open(dataDir);
		String predicateAny = "SELECT DISTINCT ?p WHERE { "
				+ "?a a <" + NS + "SomeClass> . ?a ?p ?value }";
		String pairPresence = "SELECT DISTINCT ?a ?p WHERE { "
				+ "?a a <" + NS + "SomeClass> . ?a ?p ?value }";
		String nodeAny = "SELECT DISTINCT ?a WHERE { "
				+ "?a a <" + NS + "SomeClass> . ?a ?p ?value }";
		String pairMultiplicity = "SELECT ?p (COUNT(*) AS ?count) WHERE { "
				+ "?a a <" + NS + "SomeClass> . ?a ?p ?value } GROUP BY ?p";
		String constrainedMultiplicity = "PREFIX ex: <" + NS + "> "
				+ "SELECT ?p (COUNT(*) AS ?count) WHERE { VALUES (?a ?value) { "
				+ "(ex:s0 ex:o0) (ex:s1 ex:o1) } ?a a ex:SomeClass . ?a ?p ?value } GROUP BY ?p";
		String payload = "SELECT ?a ?p ?value WHERE { "
				+ "?a a <" + NS + "SomeClass> . ?a ?p ?value }";
		String constrainedPayload = "PREFIX ex: <" + NS + "> "
				+ "SELECT ?a ?p ?value WHERE { VALUES (?a ?value) { "
				+ "(ex:s0 ex:o0) (ex:s1 ex:o1) } ?a a ex:SomeClass . ?a ?p ?value }";
		String exists = "SELECT ?a WHERE { ?a a <" + NS + "SomeClass> . "
				+ "FILTER EXISTS { ?a ?p ?value } }";

		System.setProperty(PARALLEL_PROPERTY, "false");
		System.setProperty(NATIVE_ENGINE_PROPERTY, "false");
		List<String> genericPredicateAny = allRows(predicateAny);
		List<String> genericPairPresence = allRows(pairPresence);
		List<String> genericNodeAny = allRows(nodeAny);
		List<String> genericPairMultiplicity = allRows(pairMultiplicity);
		List<String> genericConstrainedMultiplicity = allRows(constrainedMultiplicity);
		List<String> genericPayload = allRows(payload);
		List<String> genericConstrainedPayload = allRows(constrainedPayload);
		List<String> genericExists = allRows(exists);

		System.setProperty(NATIVE_ENGINE_PROPERTY, "true");
		System.setProperty(NATIVE_BATCH_ROWS_PROPERTY, "16");
		System.setProperty(PARALLEL_PROPERTY, "true");
		System.setProperty(PARALLEL_MIN_WORK_PROPERTY, "0");
		System.setProperty(PARALLEL_STARTUP_WORK_PROPERTY, "1.0E12");
		System.setProperty(PARALLEL_THREADS_PROPERTY, "2");
		System.setProperty(PARALLEL_MAX_TASKS_PROPERTY, "2");

		assertParallelWildcardParity(predicateAny, genericPredicateAny);
		assertParallelWildcardParity(pairPresence, genericPairPresence);
		assertParallelWildcardParity(nodeAny, genericNodeAny);
		assertParallelWildcardParity(pairMultiplicity, genericPairMultiplicity);
		assertParallelWildcardParity(constrainedMultiplicity, genericConstrainedMultiplicity);
		assertParallelWildcardParity(payload, genericPayload);
		assertParallelWildcardParity(constrainedPayload, genericConstrainedPayload);
		assertParallelWildcardParity(exists, genericExists);
	}

